// Serves photos stored by the local upload fallback (used when no Vercel Blob
// token is configured). Only names generated by lib/storage.ts are accepted.
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { LOCAL_DIR, LOCAL_NAME } from '@/lib/storage';

export const runtime = 'nodejs';

const TYPES: Record<string, string> = { jpg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };

export async function GET(_req: Request, { params }: { params: Promise<{ name: string }> }) {
  const { name } = await params;
  if (!LOCAL_NAME.test(name)) return new Response('Not found', { status: 404 });
  try {
    const data = await readFile(path.join(LOCAL_DIR, name));
    return new Response(new Uint8Array(data), {
      headers: {
        'Content-Type': TYPES[name.split('.').pop() as string],
        'Cache-Control': 'public, max-age=31536000, immutable',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  } catch {
    return new Response('Not found', { status: 404 });
  }
}
